    .mcB = mcB,
    .gamma = gamma,
    .Z_m = Z_m,
    .Z_min = Z_min,
    .Z_max = Z_max,
  };

  // Populate a couple more values in the context.
  ctx.psi_eval = psi_RZ(ctx.RatZeq0, 0., &ctx);
  ctx.z_min = z_psiZ(ctx.psi_eval, ctx.Z_min, &ctx);
  ctx.z_max = z_psiZ(ctx.psi_eval, ctx.Z_max, &ctx);

  return ctx;
