    poa_phases[2 * i + 1].num_frames = num_frames_fdp;
    poa_phases[2 * i + 1].duration = tau_fdp;
    poa_phases[2 * i + 1].alpha = alpha_fdp;
    poa_phases[2 * i + 1].is_static_field = is_static_field_fdp;
