+void
+eval_f_ion_source(double t, const double *GKYL_RESTRICT xn, double *GKYL_RESTRICT fout, void *ctx)
+{
+  struct gk_mirror_ctx *app = ctx;
+  double z = xn[0];
+  if (fabs(z) > app->Z_m) {
+    fout[0] = 1e-20;
+    return;
+  }
+  double vpar = xn[1];
+  double mu = xn[2];
