+  // Read the magnetic field from this input's mapc2p geometry.
+  double bvec[3];
+  double xc_in[3] = {app->psi_eval, 0.0, z};
+  bfield_func(t, xc_in, bvec, ctx);
+  double Bmag = sqrt(bvec[0] * bvec[0] + bvec[1] * bvec[1] + bvec[2] * bvec[2]);
