    fout[0] = app->Ti0 * pow((1.0 - pow((R - app->R_bt) / app->alim, 2)), app->alphaIC1 / 2);
  } else {
    fout[0] = app->Ti_m * sqrt(Bmag / app->B_m);
  }
}

