  mapc2p_vel_ion(0.0, vc_right, mapped_right, &ctx);
  check_close(mapped_left[1], mapped_right[1]);
  printf("PASS: source peaks, energy mapping, support, finite values, initial state, and velocity maps; Bmid = %.15g T\n", ctx.Bmag_midp);
  return 0;
}

