+  double cvpar = vc[0], cmu = vc[1];
+  double b = 1.4;
+  vp[0] = app->vpar_max_ion * tan(cvpar * b) / tan(b);
+
+  double transition = 0.2;
+  int power = 3;
+  if (cmu < transition) {
+    vp[1] = app->mu_max_ion * pow(transition, power - 1) * cmu;
+  } else {
+    vp[1] = app->mu_max_ion * pow(cmu, power);
+  }
